#include <stdio.h>
// 总线带宽(MB/s) = 总线位宽/8 × 时钟频率(MHz) × 每周期传输次数
int main() {
    int width_bit = 32;
    double freq_mhz = 33.0;
    int tpc = 1;                       // 每时钟周期传输次数
    double bw = (width_bit / 8.0) * freq_mhz * tpc;
    printf("总线带宽计算\n");
    printf("位宽=%d bit (= %d 字节/拍), 时钟=%.0f MHz, 每周期传输=%d 次\n",
           width_bit, width_bit / 8, freq_mhz, tpc);
    printf("带宽 = %d/8 × %.0f × %d = %.0f MB/s\n", width_bit, freq_mhz, tpc, bw);
    int w2 = 64; double f2 = 100.0;
    double bw2 = (w2 / 8.0) * f2 * 1;
    printf("对比: %d 位 %.0f MHz -> %.0f MB/s\n", w2, f2, bw2);
    return 0;
}
